async function getCompanyInfrastructure(companyId) {
  try {
    const response = await fetch('/api/vector-memory', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'getCompanyInfrastructure',
        companyId: companyId
      })
    });

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const result = await response.json();

    if (!result.success) {
      throw new Error(result.error || 'Failed to get company infrastructure');
    }

    return {
      success: true,
      infrastructure: result.infrastructure,
      totalEntities: result.infrastructure.length,
      companyId: companyId,
      message: `Retrieved ${result.infrastructure.length} infrastructure entities for company ${companyId}`,
      timestamp: new Date().toISOString()
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      timestamp: new Date().toISOString()
    };
  }
}
